    chunkOverlap: 0,
    chunkingVersion: MEMORY_CHUNKING_VERSION,
    ftsTokenizer: "unicode61",
    provenanceVersion: MEMORY_INDEX_PROVENANCE_VERSION,
  };
  const identityParams = {
